def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
    opp_d = n - opp_c

    recent_len = 10 if n >= 10 else n
    recent_c = 0
    recent_d = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_d += 1
        else:
            recent_c += 1

    forgive = 0
    for i in range(1, n - 1):
        if (
            history[i - 1][0] == 'D'
            and history[i - 1][1] == 'C'
            and history[i][0] == 'C'
            and history[i][1] == 'C'
        ):
            forgive += 1

    failed = False
    start = n - 12
    if start < 0:
        start = 0
    for i in range(start, n - 2):
        if (
            history[i][0] == 'D'
            and history[i][1] == 'D'
            and history[i + 1][0] == 'C'
            and history[i + 1][1] == 'D'
            and history[i + 2][0] == 'C'
            and history[i + 2][1] == 'D'
        ):
            failed = True
            break

    hostile = (recent_c == 0 and n >= 30) or (opp_c <= 1 and n >= 60)
    allow_recovery = (not hostile) and (not failed)

    my_prev, opp_prev = history[-1]

    if n == 99:
        return 'D'

    if n == 98:
        if allow_recovery and history[-1][0] == 'D' and history[-1][1] == 'D':
            return 'C'
        return 'D'

    if opp_prev == 'D':
        if my_prev == 'D':
            if allow_recovery:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'D':
            if allow_recovery:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][1] == 'D':
            return 'D'

        if hostile or recent_d >= 8 or (opp_d >= 5 and opp_d * 2 >= n):
            return 'D'

        return 'C'

    if my_prev == 'D':
        if (
            not hostile
            and forgive >= 2
            and recent_d <= 1
            and rng.random() < 0.35
        ):
            return 'D'
        return 'C'

    if not hostile and recent_d == 0 and n >= 18:
        if forgive >= 2 and rng.random() < 0.20:
            return 'D'
        if opp_d == 0 and rng.random() < 0.06:
            return 'D'
        if opp_d <= 3 and n >= 30 and rng.random() < 0.03:
            return 'D'

    return 'C'
